import Handlebars from 'handlebars';
import set from '../helper/format/set.js';

Handlebars.registerHelper('set', set);

describe('set helper', () => {
    it('should create a variable and use it in the template', () => {
        const template = Handlebars.compile(`
            {{{set "_limit" 10}}}
            {{_limit}}
        `);
        const result = template({});
        expect(result.trim()).toBe('10');
    });

    it('should overwrite an existing variable in the template', () => {
        const template = Handlebars.compile(`
            {{{set "_limit" 10}}}
            {{{set "_limit" 20}}}
            {{_limit}}
        `);
        const result = template({});
        expect(result.trim()).toBe('20');
    });

    it('should handle invalid variable names gracefully', () => {
        const template = Handlebars.compile(`
            {{{set 123 "invalid"}}}
            {{123}}
        `);
        const result = template({});
        expect(result.trim()).toBe(''); // Немає змінної, бо ім'я некоректне
    });

    it('should return an empty string after execution', () => {
        const template = Handlebars.compile(`
            {{{set "_limit" 10}}}
        `);
        const result = template({});
        expect(result.trim()).toBe(''); // set повертає порожній рядок
    });

    it('should not affect unrelated variables', () => {
        const template = Handlebars.compile(`
            {{{set "_limit" 10}}}
            {{otherVar}}
        `);
        const result = template({ otherVar: 'test' });
        expect(result.trim()).toBe('test');
    });
});
